from pathlib import Path
import re,base64,hashlib,shutil,datetime
p=Path('/opt/kiwoom/dashboard-source/dist/index.html');s=p.read_text();pattern='(<script id="real-operation-status-module">)([\\s\\S]*?)(</script>)'
m=re.search(pattern,s);assert m
assert hashlib.sha256(m[2].strip().encode()).hexdigest()=='613f005e674c91ef7f120b3a095ce786627dcaeb050fe5c38f0587c84cfc18a8'
suffix='.before-operation-layout-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S');shutil.copy2(p,str(p)+suffix)
u=base64.b64decode('').decode();p.write_text(re.sub(pattern,lambda m:m[1]+'\n'+u+'\n'+m[3],s));print('OPERATION_LAYOUT_DEPLOYED',suffix)
